CREATE OR REPLACE PROCEDURE dswtdip2_iot_da_dbo.sp_iot_da_export_intap(INOUT p_refcur refcursor)
 LANGUAGE plpgsql
AS $procedure$
BEGIN
    OPEN p_refcur FOR
    SELECT
        counter, doc_date, "Pstg date", type, cocd, curr, transldate, exchange_rate, ledger_group, period, reference, document_header_text, pk, gl_acct, specialgl, amount_in_doc_curr, amount_in_local_curr, amount_in_local_cur_2, ref_key_1, ref_key_2, ref_key_3, bline_date, purch_doc, purchasinglineitem, wbs_element, material, plnt, value_date, payt, "Order", cost_ctr, profit_ctr, partner_profit_center, tr_prt, assignment, text, quantity, uom, brand, subproduct_a, subproduct_b, franchise_area, business_center, revenue_type, event, vat_tax_code, "MVNO Partner", technology, "Charge Code", "Plan Type", name, street, country, "Postal Code", city, "Bank Key", "Bank Account", "Tax Number", "General Ledger Account", message, "Main Asset Number", "Base Tax Amount", "Withholding Tax Type", "Withholding Tax Code", "Payment Method", "New Company Code", "Local file for upload/download", "Error Flag", "core product", "Product lines", dsp_order, dsp_uniquekey
        FROM (SELECT
            2 AS sororder, counter, doc_date, "Pstg date", type, cocd, curr, transldate, exchange_rate, ledger_group, period, reference, document_header_text, pk, gl_acct, specialgl, amount_in_doc_curr, amount_in_local_curr, amount_in_local_cur_2, ref_key_1, ref_key_2, ref_key_3, bline_date, purch_doc, purchasinglineitem, wbs_element, material, plnt, value_date, payt, "Order", cost_ctr, profit_ctr, partner_profit_center, tr_prt, assignment, text, quantity, uom, brand, subproduct_a, subproduct_b, franchise_area, business_center, revenue_type, event, vat_tax_code, "MVNO Partner", technology, "Charge Code", "Plan Type", name, street, country, "Postal Code", city, "Bank Key", "Bank Account", "Tax Number", "General Ledger Account", message, "Main Asset Number", "Base Tax Amount", "Withholding Tax Type", "Withholding Tax Code", "Payment Method", "New Company Code", "Local file for upload/download", "Error Flag", "core product", "Product lines", dsp_order, dsp_uniquekey
            FROM dswtdip2_iot_da_dbo.txiot_da_intap_loadfile
        UNION ALL
        SELECT
            1 AS sortorder, 'Counter', 'Doc_Date', 'Pstg date', 'Type', 'CoCd', 'CURR', 'TranslDate', 'Exchange_Rate', 'Ledger_Group', 'Period', 'Reference', 'Document_header_text', 'PK', 'GL_acct', 'SpecialGL', 'Amount_in_doc_curr', 'Amount_in_local_curr', 'Amount_in_local_cur_2', 'Ref_key_1', 'Ref_key_2', 'Ref_key_3', 'Bline_date', 'Purch_doc', 'PurchasingLineItem', 'WBS_Element', 'Material', 'Plnt', 'Value_date', 'PayT', 'Order', 'Cost_ctr', 'Profit_ctr', 'Partner_Profit_Center', 'Tr_prt', 'Assignment', 'Text', 'Quantity', 'UoM', 'Brand', 'SubProduct_A', 'SubProduct_B', 'Franchise_Area', 'Business_Center', 'Revenue_Type', 'Event', 'Vat_Tax_Code', 'MVNO Partner', 'Technology', 'Charge Code', 'Plan Type', 'Name', 'Street', 'Country', 'Postal Code', 'City', 'Bank Key', 'Bank Account', 'Tax Number', 'General Ledger Account', 'Message', 'Main Asset Number', 'Base Tax Amount', 'Withholding Tax Type', 'Withholding Tax Code', 'Payment Method', 'New Company Code', 'Local file for upload/download', 'Error Flag', 'core product', 'Product lines', 'DSP_Order', 'DSP_UniqueKey') AS sub
        ORDER BY sororder NULLS FIRST;
END;
$procedure$
